package vn.gasstation.report.application;
import java.time.LocalDate;import java.time.ZoneId;import org.slf4j.*;import org.springframework.stereotype.Service;import vn.gasstation.report.domain.RevenueReport;
@Service public class RevenueReportService {private static final Logger log=LoggerFactory.getLogger(RevenueReportService.class);private final RevenueReportProvider provider;public RevenueReportService(RevenueReportProvider provider){this.provider=provider;}public RevenueReport get(LocalDate from,LocalDate to){LocalDate today=LocalDate.now(ZoneId.of("Asia/Ho_Chi_Minh"));LocalDate effectiveFrom=from==null?today:from,effectiveTo=to==null?today:to;if(effectiveFrom.isAfter(effectiveTo))throw new IllegalArgumentException("from must not be after to");var result=provider.get(effectiveFrom,effectiveTo);log.info("[BUSINESS] event=revenue-report.generated from={} to={} fuelRows={} pumpRows={} invoiceRows={}",effectiveFrom,effectiveTo,result.fuels().size(),result.pumps().size(),result.invoices().size());return result;}}
